insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r49-finance-bank'), 1, 'Every bank line has its record', '[{"caption":"The download","say":"Each week, download the account''s transactions from RBC online banking as CSV or OFX and drop the file on Bank lines. Only the lines are saved, never the full account number. The same days twice add nothing.","visual":{"kind":"title","heading":"Import from RBC","text":"CSV or OFX, once a week"}},{"caption":"Matched by themselves","say":"A line that fits exactly one record matches by itself: a Stripe payout, an e-Transfer received, an owner payout, a commission, an expense.","visual":{"kind":"list","heading":"Matched by themselves","items":["Stripe payouts","Payments received","Payouts and expenses"]}},{"caption":"The rest","say":"For the rest, pick the record that fits, record what is missing first, or set the line aside with what it is, like a bank fee. A line with no match after two days is a To do.","visual":{"kind":"list","heading":"No match","items":["Pick the record","Record it first","Set aside with the reason"]}},{"caption":"The dashboard","say":"Free cash is the bank and Stripe, less the deposits held, the owner payouts due, the refunds owed and the HST owed. An Insurance Fee never carries HST.","visual":{"kind":"title","heading":"Free cash","text":"What is really ours"}}]'::jsonb)
  on conflict do nothing;
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values
