  ((select id from academy_sections where slug = 'r49-finance-bank'), 2, 'A bank line of $6.00 is RBC''s monthly fee. What do you do?', '["Leave it unmatched","Set it aside, saying it is the monthly bank fee","Match it to any payment","Delete it"]'::jsonb, 1, 'A line that is not a payout, payment or expense is set aside with what it is; it then counts as accounted for.'),
  ((select id from academy_sections where slug = 'r49-finance-bank'), 3, 'Money came in that no record fits. What first?', '["Set it aside","Record the payment it is (for example an e-Transfer on the booking), then match the line","Wait a month","Tell the renter"]'::jsonb, 1, 'Record what it is first; the line then fits that record and is matched to it.'),
  ((select id from academy_sections where slug = 'r49-finance-bank'), 4, 'Does an Insurance Fee carry HST?', '["Yes, 13%","Never: a line that does is listed in red to correct","Only for owners with an HST number","Only on the first month"]'::jsonb, 1, 'The Insurance Fee never carries HST; the dashboard lists any invoice line that does.'),
  ((select id from academy_sections where slug = 'r49-finance-bank'), 5, 'What is Free cash?', '["The bank balance","The bank and Stripe, less deposits held, owner payouts due, refunds owed and HST owed","Money in this month","Stripe''s available balance"]'::jsonb, 1, 'Deposits, payouts due, refunds and HST are money held for others.')
